def claim_event(
    conn: sqlite3.Connection, *, event_id: str, merchant_id: str, amount_paise: int
) -> sqlite3.Row | None:
    """Record a bank event exactly once.

    Returns None when this call recorded the event (the caller must apply the
    ledger credit in the same transaction), or the already-recorded row when the
    event_id was seen before. The primary key on event_id arbitrates, so the
    check is safe when two workers race.
    """
    try:
        conn.execute(
            "INSERT INTO webhook_events (event_id, merchant_id, amount_paise) VALUES (?, ?, ?)",
            (event_id, merchant_id, amount_paise),
        )
    except sqlite3.IntegrityError:
        existing = conn.execute(
            "SELECT * FROM webhook_events WHERE event_id = ?", (event_id,)
        ).fetchone()
        if existing is None:
            raise
        return existing
    return None


