"""Settlement webhooks from the acquiring bank.

The bank retries deliveries, so the same event can arrive more than once. Every
delivery for a settlement.completed event is deduplicated on the bank's
event_id: the dedupe row and the ledger credit commit together, so a duplicate
delivery returns the same success response as the first one without crediting
again.
"""

import hashlib
import hmac
import json
import logging
import os

from fastapi import APIRouter, Header, HTTPException, Request
from pydantic import BaseModel, Field, ValidationError

from app import db
from app.ledger import store

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/webhooks", tags=["webhooks"])

CREDITED = {"status": "credited"}
IGNORED = {"status": "ignored"}


class SettlementEvent(BaseModel):
    event_id: str = Field(min_length=1, max_length=128)
    type: str
    merchant_id: str = Field(min_length=1, max_length=64)
    amount_paise: int = Field(gt=0)


def _secret() -> bytes:
    secret = os.environ.get("SETTLEMENT_WEBHOOK_SECRET")
    if not secret:
        raise RuntimeError("SETTLEMENT_WEBHOOK_SECRET is not set")
    return secret.encode()


def sign(body: bytes) -> str:
    return hmac.new(_secret(), body, hashlib.sha256).hexdigest()


def _parse(body: bytes) -> SettlementEvent:
    try:
        return SettlementEvent.model_validate(json.loads(body))
    except (json.JSONDecodeError, ValidationError):
        raise HTTPException(400, "malformed settlement event") from None


@router.post("/settlement", status_code=200)
async def settlement_webhook(request: Request, x_signature: str = Header()) -> dict:
    body = await request.body()
    # Signature check stays first: nothing is read or written before it passes.
    if not hmac.compare_digest(sign(body), x_signature):
        raise HTTPException(401, "bad signature")

    event = _parse(body)
    if event.type != "settlement.completed":
        return IGNORED

    with db.transaction() as conn:
        existing = store.claim_event(
            conn,
            event_id=event.event_id,
            merchant_id=event.merchant_id,
            amount_paise=event.amount_paise,
        )
        if existing is None:
            store.credit(
                conn, event.merchant_id, event.amount_paise, reference=event.event_id
            )
            return CREDITED

    # Duplicate: answer with success so the bank stops retrying, but credit nothing.
    if (existing["merchant_id"], existing["amount_paise"]) != (
        event.merchant_id,
        event.amount_paise,
    ):
        logger.warning(
            "settlement webhook replay differs from recorded event event_id=%s",
            event.event_id,
        )
    logger.info("settlement webhook duplicate suppressed event_id=%s", event.event_id)
    return CREDITED
